{
  "name": "PowerSight Accuracy Analyzer",
  "description": "A visualization system for power station accuracy calculations. Supports regional logic switching (Shanxi, Northwest, etc.) and manual parameter adjustment."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Region = 'Shanxi' | 'Northwest' | 'Northeast' | 'South' | 'East' | 'Central';

export interface DataPoint {
  time: string;
  real: number; // Real power
  forecast: number; // For simple logic
  // Ultra-short term forecast points (val_15, val_30 ... val_240)
  forecasts: number[]; 
}

export interface DailyResult {
  date: string;
  accuracy: number; // 0 to 1 (or score)
  mae: number;
  rmse: number;
  avgReal: number;
  avgFore: number;
}

export interface CalculationParams {
  cap: number; // Station Capacity
  threshold: number; // e.g., 0.03 (3%) for dead band
  ignoreDeadBand: boolean;
}

export interface CalculationStats {
  meanAccuracy: number;
  maxAccuracy: number;
  minAccuracy: number;
  stdDev: number;
  distribution: {
    high: number; // >= 80%
    medium: number; // 60-80%
    low: number; // < 60%
  };
}

// Basic math helpers to replace numpy behavior

export const mean = (arr: number[]): number => {
  if (arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
};

export const sum = (arr: number[]): number => {
  return arr.reduce((a, b) => a + b, 0);
};

export const rmse = (real: number[], fore: number[]): number => {
  if (real.length !== fore.length || real.length === 0) return 0;
  const squaredDiffs = real.map((r, i) => Math.pow(r - fore[i], 2));
  return Math.sqrt(mean(squaredDiffs));
};

export const mae = (real: number[], fore: number[]): number => {
  if (real.length !== fore.length || real.length === 0) return 0;
  const absDiffs = real.map((r, i) => Math.abs(r - fore[i]));
  return mean(absDiffs);
};

import { DataPoint, CalculationParams } from '../types';
import { mean, sum, rmse, mae } from './mathUtils';

// --- Specific Logic Implementations ---

/**
 * 山西 (Shanxi)
 * Logic: 1 - sqrt( sum((R-F)^2 * |R-F| / sum(|R-F|)) ) / Cap
 * Note: If sum(|R-F|) is 0, it means perfect prediction.
 */
const calcShanxiAccuracy = (real: number[], fore: number[], cap: number): number => {
  if (real.length === 0) return 1;

  const diffs = real.map((r, i) => r - fore[i]);
  const absDiffs = diffs.map(Math.abs);
  const sumAbsDiff = sum(absDiffs);

  if (sumAbsDiff === 0) return 1; // Perfect match

  const weightedSquaredErrors = diffs.map((d, i) => (Math.pow(d, 2) * absDiffs[i]) / sumAbsDiff);
  const weightedSum = sum(weightedSquaredErrors);

  const error = Math.sqrt(weightedSum) / cap;
  return Math.max(0, 1 - error);
};

/**
 * 西北 (Northwest)
 * Logic: Harmonic Mean approach
 * Harmean = 1 - 2 * sum( |R/(R+F) - 0.5| * |R-F| / sum(|R-F|) )
 */
const calcNorthwestAccuracy = (real: number[], fore: number[], cap: number, threshold: number): number => {
  // Filter out dead band (both < 3% cap)
  const validIndices: number[] = [];
  for(let i=0; i<real.length; i++) {
    if (!(real[i] < cap * threshold && fore[i] < cap * threshold)) {
      validIndices.push(i);
    }
  }

  if (validIndices.length === 0) return 1; // All data in dead band considered good

  const pSum = sum(validIndices.map(i => Math.abs(real[i] - fore[i])));
  if (pSum === 0) return 1;

  let weightedErrorSum = 0;
  validIndices.forEach(i => {
    const r = real[i];
    const f = fore[i];
    const denominator = r + f;
    const term1 = denominator === 0 ? 0 : Math.abs((r / denominator) - 0.5);
    const term2 = Math.abs(r - f);
    weightedErrorSum += term1 * (term2 / pSum);
  });

  return Math.max(0, 1 - 2 * weightedErrorSum);
};

/**
 * 东北 (Northeast)
 * Logic: Average of point-wise errors.
 * If Real < 10% Cap and Fore < 10% Cap -> Error = 0
 * Else Error = |Fore - Real| / Fore
 * Capped at 1.
 */
const calcNortheastAccuracy = (real: number[], fore: number[], cap: number): number => {
  const errors: number[] = [];

  for(let i=0; i<real.length; i++) {
    const r = real[i];
    const f = fore[i];

    if (r < cap * 0.1 && f < cap * 0.1) {
      errors.push(0);
    } else {
      // Avoid division by zero
      const denominator = f === 0 ? 0.001 : f; 
      let error = Math.abs(f - r) / denominator;
      if (error > 1) error = 1;
      errors.push(error);
    }
  }

  const meanError = mean(errors);
  return 1 - meanError;
};

/**
 * Standard RMSE (Used for Central/Hunan etc)
 */
const calcStandardRmseAccuracy = (real: number[], fore: number[], cap: number): number => {
  const r_val = rmse(real, fore);
  return Math.max(0, 1 - (r_val / cap));
};

/**
 * 南方 (South)
 * Logic based on power bands.
 * If Real < 20% Cap: Error = ((R-F)/(0.2*Cap))^2
 * If Real >= 20% Cap: Error = ((R-F)/R)^2
 * Final = 1 - sqrt(mean(Error))
 */
const calcSouthAccuracy = (real: number[], fore: number[], cap: number): number => {
  // Filter: Real >= 10% Cap OR Fore >= 10% Cap
  const validIndices: number[] = [];
  for(let i=0; i<real.length; i++) {
    if (real[i] >= cap * 0.1 || fore[i] >= cap * 0.1) {
      validIndices.push(i);
    }
  }

  if (validIndices.length === 0) return 1;

  const squaredErrors = validIndices.map(i => {
    const r = real[i];
    const f = fore[i];
    if (r < 0.2 * cap) {
      return Math.pow((r - f) / (0.2 * cap), 2);
    } else {
      // Avoid div by zero, though filter implies r >= 0.1*cap usually
      const denom = r === 0 ? 0.001 : r; 
      return Math.pow((r - f) / denom, 2);
    }
  });

  const meanSqError = mean(squaredErrors);
  return Math.max(0, 1 - Math.sqrt(meanSqError));
};


// --- Main Router ---

export const calculateDailyAccuracy = (
  region: string,
  data: DataPoint[],
  params: CalculationParams
): number => {
  // Flatten data for calculations
  const real = data.map(d => d.real);

  // Logic to determine which forecast value to use. 
  // For this visualization, we assume the 'forecast' property is the aggregated/relevant value
  // OR we take the mean of the 16-point vector if available and 'forecast' is missing.
  // To keep it simple and robust:
  const fore = data.map(d => {
    if (d.forecasts && d.forecasts.length > 0) {
      // If we have vector data (ultra-short), many formulas use the 4th hour or avg.
      // For general viz, we take the mean of the vector unless specific logic (like Xibei) requires expanding it.
      // Simplification: Use the mean of the prediction vector for the single-line chart logic
      return mean(d.forecasts);
    }
    return d.forecast;
  });

  switch (region) {
    case 'Shanxi':
      return calcShanxiAccuracy(real, fore, params.cap);
    case 'Northwest':
      return calcNorthwestAccuracy(real, fore, params.cap, params.threshold);
    case 'Northeast':
      return calcNortheastAccuracy(real, fore, params.cap);
    case 'South':
      return calcSouthAccuracy(real, fore, params.cap);
    case 'Central':
    case 'East':
    default:
      return calcStandardRmseAccuracy(real, fore, params.cap);
  }
};

import React, { useRef, useState } from 'react';
import { Upload, FileText, AlertCircle } from 'lucide-react';
import { DataPoint } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: DataPoint[]) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const parsedData = parseCSV(text);
        onDataLoaded(parsedData);
      } catch (err) {
        setError('无法解析 CSV 文件。请确保包含 Time, Power 和 Forecast/val_xx 列。');
      } finally {
        setLoading(false);
      }
    };
    reader.readAsText(file);
  };

  const parseCSV = (csvText: string): DataPoint[] => {
    const lines = csvText.trim().split('\n');
    if (lines.length < 2) throw new Error("File too short");

    const headers = lines[0].split(',').map(h => h.trim().toLowerCase());

    // Detect columns
    const timeIdx = headers.findIndex(h => h.includes('time') || h.includes('timestamp') || h.includes('时间'));
    const realIdx = headers.findIndex(h => h.includes('real') || h.includes('power') || h.includes('实际'));

    // Detect forecast columns (simple or ultra-short vector)
    const simpleForeIdx = headers.findIndex(h => h.includes('forecast') || h.includes('pred') || h.includes('预测'));
    const vectorIndices: number[] = [];
    headers.forEach((h, i) => {
      if (h.startsWith('val_')) vectorIndices.push(i);
    });

    if (timeIdx === -1 || realIdx === -1) {
      throw new Error("Missing critical columns (Time or Power)");
    }

    const result: DataPoint[] = [];

    for (let i = 1; i < lines.length; i++) {
      const currentLine = lines[i].split(',');
      if (currentLine.length < headers.length) continue;

      const realVal = parseFloat(currentLine[realIdx]);
      if (isNaN(realVal)) continue;

      let foreVal = 0;
      const foreVector: number[] = [];

      // Logic: Prefer vector data if available (Ultra-short term), else simple column
      if (vectorIndices.length > 0) {
        vectorIndices.forEach(idx => {
          const val = parseFloat(currentLine[idx]);
          if (!isNaN(val)) foreVector.push(val);
        });
        // If vector exists, simple forecast is the mean for visualization purposes
        if (foreVector.length > 0) {
            foreVal = foreVector.reduce((a, b) => a + b, 0) / foreVector.length;
        }
      } else if (simpleForeIdx !== -1) {
        foreVal = parseFloat(currentLine[simpleForeIdx]);
      }

      result.push({
        time: currentLine[timeIdx],
        real: realVal,
        forecast: isNaN(foreVal) ? 0 : foreVal,
        forecasts: foreVector
      });
    }

    if (result.length === 0) throw new Error("No valid data rows found");
    return result;
  };

  return (
    <div className="w-full max-w-xl mx-auto mb-8">
      <div 
        className="border-2 border-dashed border-slate-300 rounded-lg p-8 flex flex-col items-center justify-center bg-white hover:bg-slate-50 transition cursor-pointer"
        onClick={() => fileInputRef.current?.click()}
      >
        <Upload className="w-12 h-12 text-blue-500 mb-4" />
        <h3 className="text-lg font-semibold text-slate-700">上传场站数据</h3>
        <p className="text-sm text-slate-500 mt-2">支持 CSV 格式 (需包含时间、实际功率、预测功率)</p>
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          accept=".csv"
          className="hidden" 
        />
        {loading && <p className="mt-4 text-blue-600">正在解析数据...</p>}
      </div>

      {error && (
        <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-md flex items-center text-red-700">
          <AlertCircle className="w-5 h-5 mr-2" />
          {error}
        </div>
      )}
    </div>
  );
};

export default FileUpload;

import React from 'react';
import { Settings, MapPin, Zap } from 'lucide-react';
import { Region, CalculationParams } from '../types';

interface ControlsProps {
  region: Region;
  setRegion: (r: Region) => void;
  params: CalculationParams;
  setParams: (p: CalculationParams) => void;
  dataLoaded: boolean;
}

const Controls: React.FC<ControlsProps> = ({ region, setRegion, params, setParams, dataLoaded }) => {

  const regions: Region[] = ['Shanxi', 'Northwest', 'Northeast', 'South', 'East', 'Central'];
  const regionNames: Record<Region, string> = {
    'Shanxi': '山西 (Shanxi)',
    'Northwest': '西北 (Northwest)',
    'Northeast': '东北 (Dongbei)',
    'South': '南方 (South)',
    'East': '华东 (Huadong)',
    'Central': '华中 (Central)'
  };

  if (!dataLoaded) return null;

  return (
    <div className="bg-white rounded-lg shadow p-6 mb-6">
      <div className="flex items-center mb-4 pb-4 border-b border-slate-100">
        <Settings className="w-5 h-5 text-slate-500 mr-2" />
        <h2 className="text-lg font-bold text-slate-800">计算参数配置 (Configuration)</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Region Selector */}
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2 flex items-center">
            <MapPin className="w-4 h-4 mr-1" />
            考核区域 (Region)
          </label>
          <select 
            value={region} 
            onChange={(e) => setRegion(e.target.value as Region)}
            className="w-full border-slate-300 rounded-md shadow-sm p-2 border focus:ring-blue-500 focus:border-blue-500 bg-slate-50"
          >
            {regions.map(r => (
              <option key={r} value={r}>{regionNames[r]}</option>
            ))}
          </select>
          <p className="text-xs text-slate-500 mt-1">
            切换区域会自动应用对应的双细则公式
          </p>
        </div>

        {/* Capacity Input */}
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2 flex items-center">
            <Zap className="w-4 h-4 mr-1" />
            场站装机容量 (Capacity MW)
          </label>
          <input 
            type="number" 
            value={params.cap}
            onChange={(e) => setParams({...params, cap: Number(e.target.value)})}
            className="w-full border-slate-300 rounded-md shadow-sm p-2 border focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        {/* Threshold Input */}
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            考核死区阈值 (Threshold Ratio)
          </label>
          <div className="flex items-center space-x-2">
            <input 
              type="range" 
              min="0" 
              max="0.1" 
              step="0.01"
              value={params.threshold}
              onChange={(e) => setParams({...params, threshold: Number(e.target.value)})}
              className="flex-1"
            />
            <span className="text-sm font-mono w-12">{(params.threshold * 100).toFixed(0)}%</span>
          </div>
          <p className="text-xs text-slate-500 mt-1">
            通常用于西北/山西的免考核功率带 (e.g., 3%)
          </p>
        </div>
      </div>
    </div>
  );
};

export default Controls;

import React, { useMemo } from 'react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { DailyResult, CalculationStats } from '../types';

interface AccuracyChartsProps {
  results: DailyResult[];
  stats: CalculationStats;
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444']; // Green, Yellow, Red

const AccuracyCharts: React.FC<AccuracyChartsProps> = ({ results, stats }) => {

  const pieData = useMemo(() => [
    { name: '高准确率 (≥80%)', value: stats.distribution.high },
    { name: '中等准确率 (60-80%)', value: stats.distribution.medium },
    { name: '低准确率 (<60%)', value: stats.distribution.low },
  ].filter(d => d.value > 0), [stats]);

  // Format date for chart
  const chartData = useMemo(() => {
      return results.map(r => ({
          ...r,
          accuracyPct: parseFloat((r.accuracy * 100).toFixed(2)),
          shortDate: r.date.substring(5) // MM-DD
      }));
  }, [results]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">

      {/* Main Trend Line */}
      <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">准确率趋势 (Daily Accuracy Trend)</h3>
        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
              <XAxis dataKey="shortDate" stroke="#64748B" fontSize={12} />
              <YAxis domain={[0, 100]} stroke="#64748B" fontSize={12} unit="%" />
              <Tooltip 
                contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Legend />
              <Line 
                type="monotone" 
                dataKey="accuracyPct" 
                name="准确率 (%)" 
                stroke="#3B82F6" 
                strokeWidth={2} 
                dot={{ r: 3, fill: '#3B82F6' }} 
                activeDot={{ r: 6 }} 
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Distribution Pie */}
      <div className="bg-white p-6 rounded-lg shadow">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">准确率分布 (Distribution)</h3>
        <div className="h-80 flex flex-col justify-center items-center">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={90}
                paddingAngle={5}
                dataKey="value"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend verticalAlign="bottom" height={36}/>
            </PieChart>
          </ResponsiveContainer>
          <div className="text-center mt-2">
            <span className="text-3xl font-bold text-slate-700">{(stats.meanAccuracy * 100).toFixed(1)}%</span>
            <p className="text-xs text-slate-500">平均准确率</p>
          </div>
        </div>
      </div>

      {/* Power Comparison (Sample of aggregated daily power) */}
      <div className="lg:col-span-3 bg-white p-6 rounded-lg shadow">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">日均功率对比 (Daily Average Power MW)</h3>
        <div className="h-64">
           <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorReal" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8}/>
                  <stop offset="95%" stopColor="#8884d8" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="colorFore" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#82ca9d" stopOpacity={0.8}/>
                  <stop offset="95%" stopColor="#82ca9d" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <XAxis dataKey="shortDate" stroke="#64748B" fontSize={12} />
              <YAxis stroke="#64748B" fontSize={12} />
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <Tooltip />
              <Legend />
              <Area type="monotone" dataKey="avgReal" name="实际功率" stroke="#8884d8" fillOpacity={1} fill="url(#colorReal)" />
              <Area type="monotone" dataKey="avgFore" name="预测功率" stroke="#82ca9d" fillOpacity={1} fill="url(#colorFore)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default AccuracyCharts;

import React, { useState } from 'react';
import { DailyResult } from '../types';
import { ArrowUpDown, Download } from 'lucide-react';

interface DataTableProps {
  results: DailyResult[];
}

const DataTable: React.FC<DataTableProps> = ({ results }) => {
  const [sortConfig, setSortConfig] = useState<{ key: keyof DailyResult; direction: 'asc' | 'desc' } | null>(null);

  const sortedResults = React.useMemo(() => {
    let sortableItems = [...results];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [results, sortConfig]);

  const requestSort = (key: keyof DailyResult) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const exportCSV = () => {
    const header = ['日期', '准确率', 'MAE (MW)', 'RMSE (MW)', '实际均值', '预测均值'];
    const rows = results.map(r => [
      r.date, 
      (r.accuracy * 100).toFixed(2) + '%', 
      r.mae.toFixed(2), 
      r.rmse.toFixed(2), 
      r.avgReal.toFixed(2), 
      r.avgFore.toFixed(2)
    ]);

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + header.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "accuracy_report.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="bg-white shadow rounded-lg overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <h3 className="font-semibold text-slate-800">详细数据 (Detailed Data)</h3>
        <button 
          onClick={exportCSV}
          className="flex items-center px-3 py-1.5 bg-blue-600 text-white text-sm rounded hover:bg-blue-700 transition"
        >
          <Download className="w-4 h-4 mr-1" />
          导出 CSV
        </button>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200">
          <thead className="bg-slate-50">
            <tr>
              <th onClick={() => requestSort('date')} className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider cursor-pointer hover:bg-slate-100">
                <div className="flex items-center">日期 <ArrowUpDown className="w-3 h-3 ml-1" /></div>
              </th>
              <th onClick={() => requestSort('accuracy')} className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider cursor-pointer hover:bg-slate-100">
                 <div className="flex items-center">准确率 (Accuracy) <ArrowUpDown className="w-3 h-3 ml-1" /></div>
              </th>
