import React, { useState, useEffect } from 'react';
import { Activity, LayoutDashboard } from 'lucide-react';
import FileUpload from './components/FileUpload';
import Controls from './components/Controls';
import AccuracyCharts from './components/AccuracyCharts';
import DataTable from './components/DataTable';
import { DataPoint, Region, CalculationParams, DailyResult, CalculationStats } from './types';
import { calculateDailyAccuracy } from './services/formulas';
import { mean, rmse, mae } from './services/mathUtils';

const App: React.FC = () => {
  // State
  const [rawData, setRawData] = useState<DataPoint[]>([]);
  const [region, setRegion] = useState<Region>('Shanxi');
  const [params, setParams] = useState<CalculationParams>({
    cap: 100, // Default 100MW, user should change this
    threshold: 0.03, // Default 3% dead band
    ignoreDeadBand: true
  });

  const [results, setResults] = useState<DailyResult[]>([]);
  const [stats, setStats] = useState<CalculationStats | null>(null);

  // Effect to Recalculate when inputs change
  useEffect(() => {
    if (rawData.length === 0) return;

    // 1. Group by Date
    const grouped: Record<string, DataPoint[]> = {};
    rawData.forEach(pt => {
      // Assuming 'time' format "YYYY-MM-DD HH:mm" or similar ISO
      const date = pt.time.substring(0, 10); 
      if (!grouped[date]) grouped[date] = [];
      grouped[date].push(pt);
    });

    // 2. Calculate Daily
    const dailyResults: DailyResult[] = Object.keys(grouped).sort().map(date => {
      const dayData = grouped[date];

      const real = dayData.map(d => d.real);
      // Use mean of forecast vector or single forecast for simple stats
      const foreSimple = dayData.map(d => d.forecasts && d.forecasts.length > 0 ? mean(d.forecasts) : d.forecast);

      const acc = calculateDailyAccuracy(region, dayData, params);

      return {
        date,
        accuracy: acc,
        mae: mae(real, foreSimple),
        rmse: rmse(real, foreSimple),
        avgReal: mean(real),
        avgFore: mean(foreSimple)
      };
    });

    setResults(dailyResults);

    // 3. Calculate Aggregated Stats
    const accuracies = dailyResults.map(r => r.accuracy);
    setStats({
      meanAccuracy: mean(accuracies),
      maxAccuracy: Math.max(...accuracies),
      minAccuracy: Math.min(...accuracies),
      stdDev: Math.sqrt(mean(accuracies.map(a => Math.pow(a - mean(accuracies), 2)))),
      distribution: {
        high: accuracies.filter(a => a >= 0.8).length,
        medium: accuracies.filter(a => a >= 0.6 && a < 0.8).length,
        low: accuracies.filter(a => a < 0.6).length
      }
    });

  }, [rawData, region, params]);

  // Handle file load
  const handleDataLoaded = (data: DataPoint[]) => {
    // Auto-detect Cap estimate if possible (max of real power)
    const maxReal = Math.max(...data.map(d => d.real));
    setParams(prev => ({
      ...prev,
      cap: Math.ceil(maxReal * 1.1) // Estimate cap as 110% of max observed power if user hasn't set it
    }));
    setRawData(data);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <Activity className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-800">PowerSight 准确率分析系统</h1>
          </div>
          <div className="text-sm text-slate-500 flex items-center">
            <LayoutDashboard className="w-4 h-4 mr-1" />
            v1.0.0
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Upload Section */}
        {rawData.length === 0 ? (
          <div className="mt-10 animate-fade-in">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">
                可视化您的功率预测准确率
              </h2>
              <p className="mt-4 max-w-2xl mx-auto text-xl text-slate-500">
                支持多地区双细则公式自动计算，上传场站数据即可生成详细报告。
              </p>
            </div>
            <FileUpload onDataLoaded={handleDataLoaded} />

            {/* Demo/Instruction */}
            <div className="max-w-xl mx-auto mt-12 bg-blue-50 p-6 rounded-lg border border-blue-100">
              <h4 className="font-semibold text-blue-900 mb-2">数据格式要求:</h4>
              <p className="text-sm text-blue-800">
                CSV 文件需包含表头。必要列：<code className="bg-white px-1 py-0.5 rounded border border-blue-200">Time</code> (时间), <code className="bg-white px-1 py-0.5 rounded border border-blue-200">Real Power</code> (实测). <br/>
                可选列：<code className="bg-white px-1 py-0.5 rounded border border-blue-200">Forecast</code> 或 <code className="bg-white px-1 py-0.5 rounded border border-blue-200">val_15, val_30...</code> (超短期).
              </p>
            </div>
          </div>
        ) : (
          <div className="animate-fade-in">
            {/* Top Controls */}
            <div className="flex justify-between items-center mb-6">
               <button 
                  onClick={() => setRawData([])}
                  className="text-sm text-blue-600 hover:text-blue-800 font-medium"
               >
                 &larr; 上传新文件
               </button>
               <span className="text-sm text-slate-500">
                 已加载数据点: {rawData.length} | 时间范围: {results[0]?.date} ~ {results[results.length-1]?.date}
               </span>
            </div>

            <Controls 
              region={region} 
              setRegion={setRegion} 
              params={params} 
              setParams={setParams}
              dataLoaded={true} 
            />

            {stats && (
              <>
                <AccuracyCharts results={results} stats={stats} />
                <DataTable results={results} />
              </>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

