import React, { useState, useEffect, useMemo } from 'react';
import { Activity, LayoutDashboard, Database, ArrowRight, Calendar, Filter } from 'lucide-react';
import FileUpload from './components/FileUpload';
import Controls from './components/Controls';
import AccuracyCharts from './components/AccuracyCharts';
import DataTable from './components/DataTable';
import FormulaExplainer from './components/FormulaExplainer';
import SummaryReport from './components/SummaryReport';
import { DataPoint, Region, CalculationParams, DailyResult, CalculationStats, RawRow } from './types';
import { calculateDailyAccuracy } from './services/formulas';
import { mean, rmse, mae } from './services/mathUtils';

const App: React.FC = () => {
  // --- State ---
  // Raw Data loaded from file
  const [rawRows, setRawRows] = useState<RawRow[]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);

  // Configuration
  const [realCol, setRealCol] = useState<string>('');
  const [foreCol, setForeCol] = useState<string>('');

  // Filtering
  const [dateRange, setDateRange] = useState<{start: string, end: string}>({ start: '', end: '' });

  const [region, setRegion] = useState<Region>('Shanxi');
  const [params, setParams] = useState<CalculationParams>({
    cap: 100, 
    threshold: 0.03,
    ignoreDeadBand: true
  });

  // Computed Results
  const [results, setResults] = useState<DailyResult[]>([]);
  const [stats, setStats] = useState<CalculationStats | null>(null);

  // --- Handlers ---

  const handleDataLoaded = (rows: RawRow[], headers: string[]) => {
    setRawRows(rows);
    setCsvHeaders(headers);

    // Smart default selection
    const lowerHeaders = headers.map(h => h.toLowerCase());
    const realCandidate = headers[lowerHeaders.findIndex(h => h.includes('real') || h.includes('actual') || h.includes('实际') || h.includes('power'))] || headers[1];
    const foreCandidate = headers[lowerHeaders.findIndex(h => h.includes('fore') || h.includes('pred') || h.includes('预测'))] || headers[2];

    setRealCol(realCandidate);
    setForeCol(foreCandidate);

    // Set Date Range Defaults
    if (rows.length > 0) {
      const start = new Date(rows[0].timestamp).toISOString().split('T')[0];
      const end = new Date(rows[rows.length - 1].timestamp).toISOString().split('T')[0];
      setDateRange({ start, end });
    }

    // Auto-detect Cap
    const maxVal = Math.max(...rows.map(r => typeof r[realCandidate] === 'number' ? r[realCandidate] as number : 0));
    setParams(prev => ({ ...prev, cap: Math.ceil(maxVal * 1.1) || 100 }));
  };

  // --- Computation Effect ---
  // Transforms RawRows -> DataPoints -> DailyResults
  useEffect(() => {
    if (rawRows.length === 0 || !realCol || !foreCol) return;

    // 1. Filter and Map to DataPoint[]
    const startTime = new Date(dateRange.start).getTime();
    // End time should be end of that day, so we add 24h roughly or just string compare
    // Simpler: use string comparison YYYY-MM-DD

    const activeData: DataPoint[] = [];

    for (const row of rawRows) {
      const rowDateStr = new Date(row.timestamp).toISOString().split('T')[0];
      if (rowDateStr < dateRange.start || rowDateStr > dateRange.end) continue;

      const realVal = Number(row[realCol]) || 0;
      const foreVal = Number(row[foreCol]) || 0;

      activeData.push({
        time: row.time,
        timestamp: row.timestamp,
        real: realVal,
        forecast: foreVal,
        forecasts: [] // Removed vector logic for simplicity in manual column mode, or could be re-added if user selects multiple columns
      });
    }

    if (activeData.length === 0) {
      setResults([]);
      setStats(null);
      return;
    }

    // 2. Group by Date
    const grouped: Record<string, DataPoint[]> = {};
    activeData.forEach(pt => {
      const dateKey = new Date(pt.timestamp).toISOString().substring(0, 10);
      if (!grouped[dateKey]) grouped[dateKey] = [];
      grouped[dateKey].push(pt);
    });

    // 3. Calculate Daily
    const dailyResults: DailyResult[] = Object.keys(grouped).sort().map(date => {
      const dayData = grouped[date];
      const real = dayData.map(d => d.real);
      const fore = dayData.map(d => d.forecast); // Using selected forecast column

      const acc = calculateDailyAccuracy(region, dayData, params);

      return {
        date,
        accuracy: acc,
        mae: mae(real, fore),
        rmse: rmse(real, fore),
        avgReal: mean(real),
        avgFore: mean(fore)
      };
    });

    setResults(dailyResults);

    // 4. Calculate Aggregated Stats
    const accuracies = dailyResults.map(r => r.accuracy);
    if (accuracies.length > 0) {
      setStats({
        meanAccuracy: mean(accuracies),
        maxAccuracy: Math.max(...accuracies),
        minAccuracy: Math.min(...accuracies),
        stdDev: Math.sqrt(mean(accuracies.map(a => Math.pow(a - mean(accuracies), 2)))),
        distribution: {
          high: accuracies.filter(a => a >= 0.8).length,
          medium: accuracies.filter(a => a >= 0.6 && a < 0.8).length,
          low: accuracies.filter(a => a < 0.6).length
        }
      });
    } else {
      setStats(null);
    }

  }, [rawRows, realCol, foreCol, dateRange, region, params]);


  // Sample data for explainer
  const sampleDate = results.length > 0 ? results[0].date : '';
  const sampleDataRaw = rawRows.filter(r => 
    new Date(r.timestamp).toISOString().substring(0, 10) === sampleDate
  );
  // Map sample raw data to DataPoint for the explainer component
  const sampleData: DataPoint[] = sampleDataRaw.map(r => ({
    time: r.time,
    timestamp: r.timestamp,
    real: Number(r[realCol]) || 0,
    forecast: Number(r[foreCol]) || 0,
    forecasts: []
  }));

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <Activity className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 hidden md:block">PowerSight 准确率分析系统</h1>
            <h1 className="text-lg font-bold text-slate-800 md:hidden">PowerSight</h1>
          </div>
          <div className="text-sm text-slate-500 flex items-center">
            <LayoutDashboard className="w-4 h-4 mr-1" />
            v1.2.0
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Upload Section */}
        {rawRows.length === 0 ? (
          <div className="mt-10 animate-fade-in">
             <div className="text-center mb-8">
              <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">
                可视化您的功率预测准确率
              </h2>
              <p className="mt-4 max-w-2xl mx-auto text-xl text-slate-500">
                支持 CSV 格式上传，自定义列映射与时间筛选。
              </p>
            </div>
            <FileUpload onDataLoaded={handleDataLoaded} />
          </div>
        ) : (
          <div className="animate-fade-in space-y-6">

            {/* Top Toolbar: Data Config & Filter */}
            <div className="bg-white p-4 rounded-lg shadow border border-slate-200">
               <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">

                  {/* Left: Re-upload & Info */}
                  <div className="flex flex-col">
                    <button 
                        onClick={() => setRawRows([])}
                        className="text-sm text-blue-600 hover:text-blue-800 font-medium mb-1 text-left"
                    >
                      &larr; 上传新文件
                    </button>
                    <span className="text-xs text-slate-400">
                       Total Rows: {rawRows.length}
                    </span>
                  </div>

                  {/* Middle: Column Mapping */}
                  <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 p-3 bg-slate-50 rounded-md border border-slate-100 flex-1">
                      <div className="flex items-center text-slate-700 font-medium text-sm whitespace-nowrap">
                        <Database className="w-4 h-4 mr-2 text-blue-500" />
                        参与计算列:
                      </div>

                      <div className="flex items-center gap-2 w-full sm:w-auto">
                        <label className="text-xs text-slate-500 mr-1">实测:</label>
                        <select 
                          value={realCol} 
                          onChange={e => setRealCol(e.target.value)}
                          className="block w-full sm:w-32 pl-2 pr-8 py-1 text-sm border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md"
                        >
                          {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                      </div>

                      <ArrowRight className="hidden sm:block w-4 h-4 text-slate-300" />

                      <div className="flex items-center gap-2 w-full sm:w-auto">
                        <label className="text-xs text-slate-500 mr-1">预测:</label>
                        <select 
                          value={foreCol} 
                          onChange={e => setForeCol(e.target.value)}
                          className="block w-full sm:w-32 pl-2 pr-8 py-1 text-sm border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md"
                        >
                          {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                      </div>
                  </div>

                  {/* Right: Date Filter */}
                  <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 p-3 bg-slate-50 rounded-md border border-slate-100">
                     <div className="flex items-center text-slate-700 font-medium text-sm whitespace-nowrap">
                        <Filter className="w-4 h-4 mr-2 text-blue-500" />
                        时间筛选:
                      </div>
                      <div className="flex items-center gap-2">
                        <input 
                          type="date" 
                          value={dateRange.start}
                          onChange={e => setDateRange(prev => ({ ...prev, start: e.target.value }))}
                          className="block w-32 pl-2 pr-2 py-1 text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                        />
                        <span className="text-slate-400">-</span>
                         <input 
                          type="date" 
                          value={dateRange.end}
                          onChange={e => setDateRange(prev => ({ ...prev, end: e.target.value }))}
                          className="block w-32 pl-2 pr-2 py-1 text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                        />
                      </div>
                  </div>

               </div>
            </div>

            <Controls 
              region={region} 
              setRegion={setRegion} 
              params={params} 
              setParams={setParams}
              dataLoaded={true} 
            />

            {stats && (
              <>
                <SummaryReport 
                  results={results} 
                  stats={stats} 
                  startDate={dateRange.start} 
                  endDate={dateRange.end} 
                />

                <AccuracyCharts results={results} stats={stats} />

                <DataTable results={results} />

                {sampleData.length > 0 && (
                  <FormulaExplainer 
                    region={region} 
                    params={params}
                    sampleDayData={sampleData}
                    dateStr={sampleDate}
                  />
                )}
              </>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

