    if (region === 'Shanxi') {
      // Logic: (R-F)^2 * |R-F| / Sum(|R-F|)
      const totalAbsDiff = sum(data.map(d => Math.abs(d.real - getFore(d))));

      return (
        <table className="min-w-full divide-y divide-slate-200 text-xs md:text-sm">
          <thead className="bg-slate-50">
