// --- Default Formula Source Codes ---

export const getFormulaDefaultCode = (region: string): string => {
  switch (region) {
    case 'Shanxi':
      return `
// 山西 (Shanxi) - 双细则
// Logic: 1 - sqrt( sum((R-F)^2 * |R-F| / sum(|R-F|)) ) / Cap

const diffs = real.map((r, i) => r - fore[i]);
const absDiffs = diffs.map(Math.abs);
const sumAbsDiff = absDiffs.reduce((a, b) => a + b, 0);

if (sumAbsDiff === 0) return 1; // Perfect match

let weightedSum = 0;
for (let i = 0; i < diffs.length; i++) {
  const weight = absDiffs[i] / sumAbsDiff;
  weightedSum += Math.pow(diffs[i], 2) * weight;
}

const error = Math.sqrt(weightedSum) / cap;
return Math.max(0, 1 - error);
`;
    case 'Northwest':
      return `
// 西北 (Northwest) - 双细则
// Logic: Harmonic Mean approach with Dead Band
// Accuracy = 1 - 2 * Σ ( | R/(R+F) - 0.5 | * ( |R-F| / Σ|R-F| ) )

const thresholdVal = cap * threshold;
const validIndices = [];

// 1. Filter Dead Band
for(let i=0; i < real.length; i++) {
  if (!(real[i] < thresholdVal && fore[i] < thresholdVal)) {
    validIndices.push(i);
  }
}

if (validIndices.length === 0) return 1;

// 2. Calculate Denominator Sum
let pSum = 0;
for (const i of validIndices) {
  pSum += Math.abs(real[i] - fore[i]);
}

if (pSum === 0) return 1;

// 3. Calculate Weighted Error
let weightedErrorSum = 0;
for (const i of validIndices) {
  const r = real[i];
  const f = fore[i];
  const denom = r + f;

  const term1 = denom === 0 ? 0 : Math.abs((r / denom) - 0.5);
  const term2 = Math.abs(r - f);

  weightedErrorSum += term1 * (term2 / pSum);
}

return Math.max(0, 1 - 2 * weightedErrorSum);
`;
    case 'Northeast':
      return `
// 东北 (Northeast)
// Logic: RMSE based with Dead Band (Default 10%)
// Accuracy = 1 - ( RMSE / Cap )

const thresholdVal = cap * threshold;
const squaredErrors = [];

for(let i=0; i < real.length; i++) {
  const r = real[i];
  const f = fore[i];

  // Dead Band Check
  if (r < thresholdVal && f < thresholdVal) {
    squaredErrors.push(0);
  } else {
    squaredErrors.push(Math.pow(r - f, 2));
  }
}

if (squaredErrors.length === 0) return 1;

const mse = squaredErrors.reduce((a, b) => a + b, 0) / squaredErrors.length;
const rmseVal = Math.sqrt(mse);

return Math.max(0, 1 - (rmseVal / cap));
`;
    case 'South':
      return `
// 南方 (South)
// Logic: Segmented normalization (20% boundary)

const validIndices = [];
for(let i=0; i < real.length; i++) {
  // Filter: Real >= 10% Cap OR Fore >= 10% Cap (Approx rule)
  if (real[i] >= cap * 0.1 || fore[i] >= cap * 0.1) {
    validIndices.push(i);
  }
}

if (validIndices.length === 0) return 1;

const squaredErrors = validIndices.map(i => {
  const r = real[i];
  const f = fore[i];

  if (r < 0.2 * cap) {
    return Math.pow((r - f) / (0.2 * cap), 2);
  } else {
    const denom = r === 0 ? 0.001 : r; 
    return Math.pow((r - f) / denom, 2);
  }
});

const meanSqError = squaredErrors.reduce((a,b)=>a+b,0) / squaredErrors.length;
return Math.max(0, 1 - Math.sqrt(meanSqError));
`;
    default:
      return `
// 通用 RMSE (General)
// Accuracy = 1 - ( RMSE / Cap )

if (real.length === 0) return 1;

const squaredDiffs = real.map((r, i) => Math.pow(r - fore[i], 2));
const mse = squaredDiffs.reduce((a,b)=>a+b,0) / squaredDiffs.length;
const rmseVal = Math.sqrt(mse);

return Math.max(0, 1 - (rmseVal / cap));
`;
  }
};

/**
 * Executes a custom user-defined formula string.
 * This uses the Function constructor, which is safer than eval() but still allows dynamic code execution.
 */
export const executeCustomFormula = (
  code: string,
  real: number[],
  fore: number[],
  cap: number,
  threshold: number
): number => {
  try {
    // Create a function with specific arguments available to the user's code
    // The user's code is the function body
    const func = new Function('real', 'fore', 'cap', 'threshold', code);

    // Execute
    const result = func(real, fore, cap, threshold);

    // Safety checks
    if (typeof result !== 'number' || isNaN(result)) return 0;
    return result;
  } catch (err) {
    console.error("Formula Execution Error:", err);
    return 0;
  }
};

