```typescript
export interface FormulaInfo {
  name: string;
  desc: string;
  formula: string;
}

export const getFormulaInfo = (region: string): FormulaInfo => {
  switch (region) {
    case 'Northwest':
      return {
        name: '西北双细则 (Northwest)',
        desc: '基于调和平均误差，包含死区逻辑。',
        formula: `
        let pSum = 0;
        for (const i of validIndices) {
          pSum += Math.abs(real[i] - fore[i]);
        }

        if (pSum === 0) return 1;

        let weightedErrorSum = 0;
        for (const i of validIndices) {
          const r = real[i];
          const f = fore[i];
          const denom = r + f;

          const term1 = denom === 0 ? 0 : Math.abs((r / denom) - 0.5);
          const term2 = Math.abs(r - f);

          weightedErrorSum += term1 * (term2 / pSum);
        }

        return Math.max(0, 1 - 2 * weightedErrorSum);
        `,
      };
    case 'Northeast':
      return {
        name: '东北双细则 (Northeast)',
        desc: '基于均方根误差 (RMSE)，包含死区逻辑。',
        formula: `
        const thresholdVal = cap * threshold;
