 */
export const executeCustomFormula = (
  code: string,
  real: number[],
  fore: number[],
  cap: number,
  threshold: number
): number => {
  try {
    // Create a function with specific arguments available to the user's code
    // The user's code is the function body
    const func = new Function('real', 'fore', 'cap', 'threshold', code);

    // Execute
    const result = func(real, fore, cap, threshold);

    // Safety checks
    if (typeof result !== 'number' || isNaN(result)) return 0;
    return result;
  } catch (err) {
    console.error("Formula Execution Error:", err);
    return 0;
  }
};

