import React, { useState, useEffect, useRef } from 'react';
import { Activity, LayoutDashboard, Database, ArrowRight, Filter, ChevronDown, Check, Play, Settings, FileText, ChevronRight, ChevronLeft, Loader2 } from 'lucide-react';
