// --- Pyodide Setup ---

let pyodideInstance: any = null;

declare global {
  interface Window {
    loadPyodide: any;
  }
}

export const initPyodide = async () => {
  if (pyodideInstance) return pyodideInstance;

  if (typeof window.loadPyodide !== 'function') {
    throw new Error('Pyodide script not loaded');
  }

  // Initialize Pyodide
  pyodideInstance = await window.loadPyodide();

  // Load Numpy explicitly as it is commonly used in custom logic
  await pyodideInstance.loadPackage("numpy");

  return pyodideInstance;
};

// --- AI / Smart Parsing Logic ---

/**
 * A heuristic converter that transforms user-provided functions into an executable script body.
 * It handles common patterns like converting function definitions to inline logic
 * and mapping pandas-style syntax (iloc) to list-of-list syntax.
 */
export const aiGenerateFormula = (input: string): string => {
  let code = input.trim();

  // 1. If it looks like a function definition, unwrap it
  if (code.startsWith('def ')) {
    const lines = code.split('\n');
    // Remove the 'def' line
    lines.shift();

    // Decrease indentation
    code = lines.map(line => {
      if (line.startsWith('    ')) return line.substring(4);
      if (line.startsWith('\t')) return line.substring(1);
      return line;
    }).join('\n');

    // Handle 'return' -> assign to result
    if (code.includes('return ')) {
      code = code.replace(/return\s+(.*)/g, 'result = $1');
    }
  }

  // 2. Intelligent Variable Mapping
  // Map common user variable names to our environment variables
  // Our Env: real (list), fore (list), fore_list (matrix), cap (float), threshold (float)

  // If user code uses 'fore.iloc', they likely expect a dataframe/matrix.
  // We map 'fore' to 'fore_list' (the matrix) in this context if strictly used as matrix
  if (code.includes('.iloc')) {
    code = code.replace(/fore\.iloc\[i\]/g, 'fore_list[i]');
    code = code.replace(/fore\.iloc/g, 'fore_list'); 
  }

  // 3. Ensure Numpy is imported if used
  if (code.includes('np.') && !code.includes('import numpy')) {
    code = 'import numpy as np\n' + code;
  }

  // 4. Ensure it ends with 'result'
  if (!code.trim().endsWith('result')) {
    code += '\n\nresult';
  }

  // 5. Add explanatory comments
  const header = `# AI-Parsed Logic
# Environment:
#  real: List[float]
#  fore: List[float] (Average Forecast)
#  fore_list: List[List[float]] (Raw Forecast Columns)
#  cap: float
#  threshold: float

`;

  return header + code;
};


// --- Default Formula Source Codes (Python) ---

export const getFormulaDefaultCode = (region: string): string => {
  switch (region) {
    case 'Shanxi':
      return `# 山西 (Shanxi) - 双细则 (Python)
import math

# diffs = real - fore
diffs = [r - f for r, f in zip(real, fore)]
abs_diffs = [abs(x) for x in diffs]
sum_abs_diff = sum(abs_diffs)

if sum_abs_diff == 0:
    result = 1.0
else:
    weighted_sum = 0
    for d, ad in zip(diffs, abs_diffs):
        weight = ad / sum_abs_diff
        weighted_sum += (d ** 2) * weight

    error = math.sqrt(weighted_sum) / cap
    result = max(0, 1 - error)

result`;

    case 'Northwest':
      return `# 西北 (Northwest) - 双细则 (Python)
threshold_val = cap * threshold
valid_indices = [i for i in range(len(real)) if not (real[i] < threshold_val and fore[i] < threshold_val)]

if not valid_indices:
    result = 1.0
else:
    p_sum = sum(abs(real[i] - fore[i]) for i in valid_indices)
    if p_sum == 0:
        result = 1.0
    else:
        weighted_error_sum = 0
        for i in valid_indices:
            r = real[i]
            f = fore[i]
            denom = r + f
            term1 = 0 if denom == 0 else abs((r / denom) - 0.5)
            term2 = abs(r - f)
            weighted_error_sum += term1 * (term2 / p_sum)

        result = max(0, 1 - 2 * weighted_error_sum)

result`;

    case 'Northeast':
      return `# 东北 (Northeast) (Python)
# Standard RMSE based
import math

threshold_val = cap * threshold
squared_errors = []

for r, f in zip(real, fore):
    if r < threshold_val and f < threshold_val:
        squared_errors.append(0)
    else:
        squared_errors.append((r - f)**2)

if not squared_errors:
    result = 1.0
else:
    mse = sum(squared_errors) / len(squared_errors)
    rmse = math.sqrt(mse)
    result = max(0, 1 - (rmse / cap))

result`;

    case 'South':
      return `# 南方 (South) (Python)
import math

valid_errors = []
for r, f in zip(real, fore):
    if r >= cap * 0.1 or f >= cap * 0.1:
        if r < 0.2 * cap:
            valid_errors.append(((r - f) / (0.2 * cap))**2)
        else:
            denom = 0.001 if r == 0 else r
            valid_errors.append(((r - f) / denom)**2)

if not valid_errors:
    result = 1.0
else:
    mean_sq_error = sum(valid_errors) / len(valid_errors)
    result = max(0, 1 - math.sqrt(mean_sq_error))

result`;

    default:
      return `# 通用 RMSE (General) (Python)
import math

if not real:
    result = 1.0
else:
    squared_diffs = [(r - f)**2 for r, f in zip(real, fore)]
    mse = sum(squared_diffs) / len(squared_diffs)
    rmse = math.sqrt(mse)
    result = max(0, 1 - (rmse / cap))

result`;
  }
};

/**
 * Executes custom user-defined PYTHON code using Pyodide.
 * Now accepts fore_list (List of Lists) for matrix calculations.
 */
export const executeCustomFormula = async (
  code: string,
  real: number[],
  fore: number[],
  cap: number,
  threshold: number,
  foreRaw: number[][] = [] 
): Promise<number> => {
  try {
    const py = await initPyodide();

    // Set globals for Python context
    py.globals.set("real", real);
    py.globals.set("fore", fore); // Average forecast (List)
    py.globals.set("fore_list", foreRaw); // Raw forecast columns (Matrix)
    py.globals.set("cap", cap);
    py.globals.set("threshold", threshold);

    // Execute the code
    const result = await py.runPythonAsync(code);

    // Cleanup globals
    py.globals.delete("real");
    py.globals.delete("fore");
    py.globals.delete("fore_list");
    py.globals.delete("cap");
    py.globals.delete("threshold");

    // Ensure result is a number
    const numResult = Number(result);
    if (isNaN(numResult)) return 0;
    return numResult;

  } catch (err) {
    console.error("Python Execution Error:", err);
    throw err;
  }
};

