                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                          <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">实测功率列 (Real)</label>
                            <select 
                              value={realCol} 
                              onChange={e => setRealCol(e.target.value)}
