  interface Window {
    loadPyodide: (config?: { indexURL?: string }) => Promise<any>;
    pyodide: any;
  }
}

// Ensure initPyodide is defined and ready
const initPyodide = async () => {
  if (pyodideInstance) return pyodideInstance;

  if (typeof window.loadPyodide !== 'function') {
    throw new Error('Pyodide script not loaded');
  }

  // Initialize Pyodide
  // We explicitly specify the indexURL to the CDN to ensure that 
  // pyodide.asm.js and other required files are fetched from the correct location.
  // This fixes "Failed to fetch dynamically imported module" errors.
  pyodideInstance = await window.loadPyodide({
    indexURL: "https://cdn.jsdelivr.net/pyodide/v0.23.4/full/"
  });

  // Load Numpy explicitly as it is commonly used in custom logic
  await pyodideInstance.loadPackage("numpy");

  return pyodideInstance;
};

// --- Custom Formula Execution ---

const executeCustomFormula = async (
  formula: string,
  params: CalculationParams
): Promise<{ result: number | null; error: string | null }> => {
  try {
    const pyodide = await initPyodide();

    // Convert DataPoints to Python-friendly format
    const dataPointsPython = pyodide.globals.get('dict')({});
    for (const key in params.data) {
      if (params.data.hasOwnProperty(key)) {
        dataPointsPython.set(key, params.data[key]);
      }
    }

    // Initialize the result object (crucial!)
    let result = {result: null, error: null};
    try {
      // Execute the formula within Pyodide
      const resultPython = pyodide.runPython(`
        import numpy as np

        data = ${JSON.stringify(params.data)}
        # Convert values to floats to be safe
        data = {k: float(v) for k, v in data.items()}

        ${formula}

        result = ${formula}

        result
      `);

      // Convert result to number. Catch exceptions
      if(resultPython) {
        result.result = resultPython.valueOf();
      }
    }
    catch (e:any) {
      console.error("Pyodide execution error:", e);
      result.error = e.toString();
    }
    finally {
      // Clean up Python object to avoid memory leaks
      if (dataPointsPython) {
        dataPointsPython.destroy();
      }
    }
    return result;

  } catch (error: any) {
    console.error("Error executing formula:", error);
    return { result: null, error: error.toString() };
  }
};

export { executeCustomFormula };
```

