/**
 * Executes custom user-defined PYTHON code using Pyodide.
 * Now accepts fore_list (List of Lists) for matrix calculations.
 */
export const executeCustomFormula = async (
  code: string,
  real: number[],
  fore: number[],
  cap: number,
  threshold: number,
  foreRaw: number[][] = [] 
): Promise<number> => {
  try {
    const py = await initPyodide();

    // Set globals for Python context
    py.globals.set("real", real);
    py.globals.set("fore", fore); // Average forecast (List)
    py.globals.set("fore_list", foreRaw); // Raw forecast columns (Matrix)
    py.globals.set("cap", cap);
    py.globals.set("threshold", threshold);

    // Initialize result in global scope to prevent NameError if user code fails to assign it
    // but code execution completes (e.g. logic branch skipped)
    py.runPython("result = 0.0");

    // Execute the code
    const result = await py.runPythonAsync(code);

    // Ensure result is a number
    const numResult = Number(result);
    if (isNaN(numResult)) return 0;
    return numResult;

  } catch (err) {
    console.error("Python Execution Error:", err);
    throw err;
  } finally {
      // Cleanup globals in finally block to ensure they are removed even if error occurs
      // Use try-catch to ignore KeyError if key is already deleted or missing
      if (pyodideInstance && pyodideInstance.globals) {
          try { pyodideInstance.globals.delete("real"); } catch (e) {}
          try { pyodideInstance.globals.delete("fore"); } catch (e) {}
          try { pyodideInstance.globals.delete("fore_list"); } catch (e) {}
          try { pyodideInstance.globals.delete("cap"); } catch (e) {}
          try { pyodideInstance.globals.delete("threshold"); } catch (e) {}
      }
  }
};

