                         <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-4 mt-4">
                            <h4 className="font-bold text-slate-800 mb-2 text-sm flex items-center">
                                <Check className="w-4 h-4 text-green-500 mr-2" />
