                                <li>您可以直接修改 Python 代码，或使用 <strong>AI 助手</strong>用自然语言生成代码。</li>
                                <li>修改后，点击 <strong>"测试运行 (Test Run)"</strong> 按钮，系统会使用第一天的数据进行预演，确保逻辑无误。</li>
                            </ul>
                        </div>
                    </div>

                    {/* Right Col: Formula Editor */}
                    <div className="lg:col-span-8 h-[600px]">
                        <FormulaEditor 
                          region={region} 
                          code={customFormula} 
                          setCode={setCustomFormula} 
                          sampleData={editorSampleData} 
                        />
                    </div>
                </div>

                <div className="flex justify-end pt-4 border-t border-slate-200">
                    <button 
                        onClick={handleCalculate}
                        disabled={isCalculating}
                        className="flex items-center px-8 py-3 bg-green-600 text-white font-bold rounded-lg shadow-lg hover:bg-green-700 hover:shadow-xl transform hover:-translate-y-0.5 transition disabled:opacity-70 disabled:cursor-not-allowed"
                    >
                        {isCalculating ? (
                          <>
                            <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                            计算全量数据 (Python Engine)...
                          </>
                        ) : (
                          <>
                            <Play className="w-5 h-5 mr-2" />
                            开始计算并生成报表
                          </>
                        )}
                    </button>
                </div>
            </div>
        )}

        {/* Step 3: Results */}
        {step === 3 && stats && (
            <div className="animate-fade-in space-y-6">
                <div className="flex items-center justify-between">
                     <button onClick={() => setStep(2)} className="flex items-center text-slate-500 hover:text-blue-600">
                        <ChevronLeft className="w-4 h-4 mr-1" />
                        返回参数配置
                     </button>
                     <h2 className="text-2xl font-bold text-slate-800">第三步：分析结果</h2>
                </div>

                <SummaryReport 
                  results={results} 
                  stats={stats} 
                  startDate={dateRange.start} 
                  endDate={dateRange.end} 
                />

                <AccuracyCharts results={results} stats={stats} />

                <DataTable results={results} />
            </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { RawRow } from '../types';
import { Table, ArrowRight } from 'lucide-react';

interface DataPreviewProps {
  data: RawRow[];
  realCol: string;
  foreCols: string[];
  dateRange: { start: string, end: string };
}

const DataPreview: React.FC<DataPreviewProps> = ({ data, realCol, foreCols, dateRange }) => {
  // Filter preview data based on date range (take first 10 matching)
  const previewRows = [];
  let count = 0;

  for (const row of data) {
    // Construct local date string YYYY-MM-DD
    const d = new Date(row.timestamp);
    const rowDate = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

    if (rowDate >= dateRange.start && rowDate <= dateRange.end) {
      previewRows.push(row);
      count++;
    }
    if (count >= 10) break;
  }

  return (
    <div className="bg-white rounded-lg shadow border border-slate-200 mt-6">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div className="flex items-center">
          <Table className="w-5 h-5 text-blue-600 mr-2" />
          <h3 className="font-bold text-slate-800">标准数据预览 (Standard Data Preview - Top 10)</h3>
        </div>
        <span className="text-xs text-slate-500">
            Previewing valid data range
        </span>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200 text-sm">
          <thead className="bg-slate-100">
            <tr>
              <th className="px-4 py-3 text-left font-medium text-slate-600">Time</th>
              <th className="px-4 py-3 text-left font-medium text-slate-600">
                 实测 (Real) <span className="text-xs text-slate-400 font-normal block">{realCol}</span>
              </th>
              <th className="px-4 py-3 text-left font-medium text-slate-600">
                 预测 (Forecast) <span className="text-xs text-slate-400 font-normal block">Avg of {foreCols.length} cols</span>
              </th>
              {foreCols.length > 1 && (
                 <th className="px-4 py-3 text-left font-medium text-slate-400">
                    Forecast Details
                 </th>
              )}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {previewRows.length === 0 ? (
                <tr>
                    <td colSpan={4} className="p-8 text-center text-slate-500">
                        当前时间筛选范围内无数据 (No data in selected date range)
                    </td>
                </tr>
            ) : (
                previewRows.map((row, idx) => {
                  const realVal = Number(row[realCol]) || 0;
                  const foreVals = foreCols.map(c => Number(row[c]) || 0);
                  const avgFore = foreVals.reduce((a,b)=>a+b,0) / (foreVals.length || 1);

                  return (
                    <tr key={idx} className="hover:bg-slate-50">
                      <td className="px-4 py-2 text-slate-700 whitespace-nowrap">{row.time}</td>
                      <td className="px-4 py-2 font-mono text-blue-700">{realVal.toFixed(2)}</td>
                      <td className="px-4 py-2 font-mono text-green-700">{avgFore.toFixed(2)}</td>
                      {foreCols.length > 1 && (
                          <td className="px-4 py-2 text-xs text-slate-400">
                              [{foreVals.map(v => v.toFixed(1)).join(', ')}]
                          </td>
                      )}
                    </tr>
                  );
                })
            )}
          </tbody>
        </table>
      </div>
      <div className="p-3 bg-slate-50 border-t border-slate-100 text-center text-xs text-slate-500">
         * 系统将使用上述“实测”和“预测”列数据进行后续准确率计算
      </div>
    </div>
  );
};

export default DataPreview;

import React, { useMemo } from 'react';
import { DailyResult, CalculationStats, MonthlyStats } from '../types';
import { FileText, TrendingUp, TrendingDown } from 'lucide-react';
import { mean } from '../services/mathUtils';

interface SummaryReportProps {
  results: DailyResult[];
  stats: CalculationStats;
  startDate: string;
  endDate: string;
}

const SummaryReport: React.FC<SummaryReportProps> = ({ results, stats, startDate, endDate }) => {

  const monthlyStats = useMemo(() => {
    const grouped: Record<string, DailyResult[]> = {};
    results.forEach(r => {
      const monthKey = r.date.substring(0, 7); // YYYY-MM
      if (!grouped[monthKey]) grouped[monthKey] = [];
      grouped[monthKey].push(r);
    });

    const report: MonthlyStats[] = Object.keys(grouped).sort().map(m => {
      const days = grouped[m];
      const accs = days.map(d => d.accuracy);
      return {
        month: m,
        meanAccuracy: mean(accs),
        meanRmse: mean(days.map(d => d.rmse)),
        meanMae: mean(days.map(d => d.mae)),
        distribution: {
            high: accs.filter(a => a >= 0.8).length,
            medium: accs.filter(a => a >= 0.6 && a < 0.8).length,
            low: accs.filter(a => a < 0.6).length
        },
        daysCount: days.length
      };
    });
    return report;
  }, [results]);

  // Comparative Analysis Logic
  const analysisText = useMemo(() => {
      if (monthlyStats.length === 0) return null;

      const sortedByAcc = [...monthlyStats].sort((a, b) => b.meanAccuracy - a.meanAccuracy);
      const best = sortedByAcc[0];
      const worst = sortedByAcc[sortedByAcc.length - 1];

      const monthDetails = monthlyStats.map(m => 
          `${m.month} (${(m.meanAccuracy * 100).toFixed(1)}%)`
      ).join('，');

      return {
          detailStr: monthDetails,
          best,
          worst,
          diff: (best.meanAccuracy - worst.meanAccuracy) * 100
      };
  }, [monthlyStats]);

  if (results.length === 0) return null;

  return (
    <div className="bg-white rounded-lg shadow mt-8 border border-slate-200 overflow-hidden">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center">
        <FileText className="w-5 h-5 text-blue-600 mr-2" />
        <h3 className="text-lg font-bold text-slate-800">分析报告总结 (Summary Report)</h3>
      </div>

      <div className="p-6 space-y-6">
        {/* Overall Summary */}
        <div>
            <h4 className="text-base font-semibold text-slate-700 mb-2 border-l-4 border-blue-500 pl-2">
                总体概况 ({startDate} 至 {endDate})
            </h4>
            <div className="bg-slate-50 p-4 rounded text-sm text-slate-700 leading-relaxed space-y-3">
                <p>
                    在选定的时间范围内，共计考核 <strong>{results.length}</strong> 天。
                    全时段平均准确率为 <strong className="text-blue-700">{(stats.meanAccuracy * 100).toFixed(2)}%</strong>，
                    平均 RMSE 为 <strong>{mean(results.map(r => r.rmse)).toFixed(2)} MW</strong>。
                </p>
                <p>
                    合格率分布情况：
                    <span className="text-green-600 font-medium">高准确率(≥80%) {stats.distribution.high} 天</span> (占比 {((stats.distribution.high / results.length) * 100).toFixed(1)}%)，
                    <span className="text-yellow-600 font-medium">中等(60-80%) {stats.distribution.medium} 天</span>，
                    <span className="text-red-600 font-medium">低准确率(&lt;60%) {stats.distribution.low} 天</span>。
                </p>

                {/* New Monthly Analysis Paragraph */}
                {analysisText && monthlyStats.length > 1 && (
                    <div className="pt-2 border-t border-slate-200 mt-2">
                        <p className="mb-1 font-semibold text-slate-800 flex items-center">
                             月度对比分析：
                        </p>
                        <p>
                            各月平均准确率分别为：{analysisText.detailStr}。
                        </p>
                        <div className="mt-2 flex items-start gap-4 p-3 bg-white border border-slate-100 rounded-md">
                             <div className="flex items-center text-green-700">
                                <TrendingUp className="w-4 h-4 mr-1" />
                                <span>表现最佳：<strong>{analysisText.best.month}</strong> ({(analysisText.best.meanAccuracy * 100).toFixed(2)}%)</span>
                             </div>
                             <div className="w-px h-4 bg-slate-300 mx-2 hidden sm:block"></div>
                             <div className="flex items-center text-red-700">
                                <TrendingDown className="w-4 h-4 mr-1" />
                                <span>表现最差：<strong>{analysisText.worst.month}</strong> ({(analysisText.worst.meanAccuracy * 100).toFixed(2)}%)</span>
                             </div>
                             <div className="w-px h-4 bg-slate-300 mx-2 hidden sm:block"></div>
                             <span className="text-slate-500">极差：{analysisText.diff.toFixed(2)}%</span>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Monthly Breakdown Table */}
        <div>
            <h4 className="text-base font-semibold text-slate-700 mb-2 border-l-4 border-indigo-500 pl-2">
                月度详细数据表
            </h4>
            <div className="overflow-x-auto rounded-lg border border-slate-200">
                <table className="min-w-full divide-y divide-slate-200 text-sm">
                    <thead className="bg-slate-100">
                        <tr>
                            <th className="px-4 py-2 text-left font-medium text-slate-500">月份</th>
                            <th className="px-4 py-2 text-left font-medium text-slate-500">天数</th>
                            <th className="px-4 py-2 text-left font-medium text-slate-500">平均准确率</th>
                            <th className="px-4 py-2 text-left font-medium text-slate-500">平均 RMSE</th>
                            <th className="px-4 py-2 text-left font-medium text-slate-500">分布 (高/中/低)</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                        {monthlyStats.map((stat) => (
                            <tr key={stat.month} className="hover:bg-slate-50 transition">
                                <td className="px-4 py-2 font-medium text-slate-700">{stat.month}</td>
                                <td className="px-4 py-2 text-slate-600">{stat.daysCount}</td>
                                <td className="px-4 py-2">
                                    <span className={`font-bold ${stat.meanAccuracy >= 0.8 ? 'text-green-600' : stat.meanAccuracy >= 0.6 ? 'text-yellow-600' : 'text-red-600'}`}>
                                        {(stat.meanAccuracy * 100).toFixed(2)}%
                                    </span>
                                </td>
                                <td className="px-4 py-2 text-slate-600">{stat.meanRmse.toFixed(2)}</td>
                                <td className="px-4 py-2 text-slate-500 text-xs">
                                    <span className="text-green-600 font-semibold">{stat.distribution.high}</span> / 
                                    <span className="text-yellow-600 font-semibold mx-1">{stat.distribution.medium}</span> / 
                                    <span className="text-red-600 font-semibold">{stat.distribution.low}</span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
      </div>
    </div>
  );
};

export default SummaryReport;

import React, { useMemo, useState } from 'react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { DailyResult, CalculationStats } from '../types';
import { X, Maximize2, Calendar, PieChart as PieChartIcon, Activity } from 'lucide-react';

interface AccuracyChartsProps {
  results: DailyResult[];
  stats: CalculationStats;
}

const COLORS = ['#10B981', '#F59E0B', '#EF4444']; // Green, Yellow, Red

// Helper to format chart data
const formatChartData = (data: DailyResult[]) => {
    return data.map(r => ({
        ...r,
        accuracyPct: parseFloat((r.accuracy * 100).toFixed(2)),
        shortDate: r.date.substring(8), // DD only for monthly view, or MM-DD for full
        fullShortDate: r.date.substring(5) // MM-DD
    }));
};

const AccuracyCharts: React.FC<AccuracyChartsProps> = ({ results, stats }) => {
  // Modal State
  const [zoomedView, setZoomedView] = useState<{
      type: 'trend' | 'distribution';
      month: string;
      data: DailyResult[];
      stats?: any;
  } | null>(null);

  // Overall Pie Data
  const pieData = useMemo(() => [
    { name: '高 (≥80%)', value: stats.distribution.high },
    { name: '中 (60-80%)', value: stats.distribution.medium },
    { name: '低 (<60%)', value: stats.distribution.low },
  ].filter(d => d.value > 0), [stats]);

  // Overall Trend Data
  const overallChartData = useMemo(() => formatChartData(results), [results]);

  // Group by Month
  const monthlyGroups = useMemo(() => {
    const grouped: Record<string, DailyResult[]> = {};
    results.forEach(r => {
        const m = r.date.substring(0, 7);
        if (!grouped[m]) grouped[m] = [];
        grouped[m].push(r);
    });
    return Object.keys(grouped).sort().map(m => ({
        month: m,
        data: grouped[m],
        chartData: formatChartData(grouped[m]),
        distStats: [
            { name: '高', value: grouped[m].filter(d => d.accuracy >= 0.8).length },
            { name: '中', value: grouped[m].filter(d => d.accuracy >= 0.6 && d.accuracy < 0.8).length },
            { name: '低', value: grouped[m].filter(d => d.accuracy < 0.6).length },
        ].filter(d => d.value > 0)
    }));
  }, [results]);

  // --- Zoom Modal Component ---
  const renderModal = () => {
      if (!zoomedView) return null;

      const { type, month, data, stats: modalStats } = zoomedView;
      const formattedData = formatChartData(data);

      return (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-fade-in">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl h-[500px] flex flex-col overflow-hidden">
                  <div className="flex justify-between items-center p-4 border-b border-slate-100 bg-slate-50">
                      <div className="flex items-center space-x-2">
                          <Calendar className="w-5 h-5 text-blue-600" />
                          <h3 className="text-xl font-bold text-slate-800">
                              {month} - {type === 'trend' ? '准确率趋势放大视图' : '准确率分布放大视图'}
                          </h3>
                      </div>
                      <button 
                        onClick={() => setZoomedView(null)}
                        className="p-2 hover:bg-slate-200 rounded-full transition"
                      >
                          <X className="w-6 h-6 text-slate-500" />
                      </button>
                  </div>
                  <div className="flex-1 p-6 bg-white">
                      <ResponsiveContainer width="100%" height="100%">
                          {type === 'trend' ? (
                            <LineChart data={formattedData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                <XAxis dataKey="fullShortDate" stroke="#64748B" />
                                <YAxis domain={[0, 100]} unit="%" />
                                <Tooltip contentStyle={{ borderRadius: '8px' }} />
                                <Legend />
                                <Line type="monotone" dataKey="accuracyPct" name="准确率 (%)" stroke="#3B82F6" strokeWidth={3} dot={{r:4}} activeDot={{r:8}} />
                            </LineChart>
                          ) : (
                            <PieChart>
                                <Pie
                                    data={modalStats}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={80}
                                    outerRadius={140}
                                    paddingAngle={5}
                                    dataKey="value"
                                    label={({name, value}) => `${name}: ${value}天`}
                                >
                                    {modalStats.map((entry: any, index: number) => (
                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                                <Legend />
                            </PieChart>
                          )}
                      </ResponsiveContainer>
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="space-y-8 mb-8">
      {renderModal()}

      {/* 1. Overall Big Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Trend Line */}
        <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow border border-slate-200">
          <div className="flex items-center justify-between mb-4">
             <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                <Activity className="w-5 h-5 mr-2 text-blue-500" />
                总体准确率趋势 (Overall Trend)
             </h3>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={overallChartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
                <XAxis dataKey="fullShortDate" stroke="#64748B" fontSize={12} minTickGap={30} />
                <YAxis domain={[0, 100]} stroke="#64748B" fontSize={12} unit="%" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Legend />
                <Line 
                  type="monotone" 
                  dataKey="accuracyPct" 
                  name="准确率 (%)" 
                  stroke="#3B82F6" 
                  strokeWidth={2} 
                  dot={{ r: 2, fill: '#3B82F6' }} 
                  activeDot={{ r: 6 }} 
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Overall Distribution Pie */}
        <div className="bg-white p-6 rounded-lg shadow border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center">
              <PieChartIcon className="w-5 h-5 mr-2 text-orange-500" />
              总体分布 (Overall Dist)
          </h3>
          <div className="h-80 flex flex-col justify-center items-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={90}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
            <div className="text-center mt-2">
              <span className="text-3xl font-bold text-slate-700">{(stats.meanAccuracy * 100).toFixed(1)}%</span>
              <p className="text-xs text-slate-500">平均准确率</p>
            </div>
          </div>
        </div>
      </div>

      {/* 2. Monthly Trend Grid (Small Multiples) */}
      {monthlyGroups.length > 0 && (
          <div className="bg-white p-6 rounded-lg shadow border border-slate-200">
              <div className="mb-4 pb-2 border-b border-slate-100">
                  <h3 className="text-lg font-bold text-slate-800 flex items-center">
                      <Calendar className="w-5 h-5 mr-2 text-indigo-500" />
                      月度准确率趋势图 (Monthly Trends)
                  </h3>
                  <p className="text-xs text-slate-500 mt-1">点击任意图表可放大查看详情</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {monthlyGroups.map((group) => (
                      <div 
                        key={group.month} 
                        className="border border-slate-100 rounded-lg p-3 hover:shadow-md transition cursor-pointer group bg-slate-50 hover:bg-white relative"
                        onClick={() => setZoomedView({ type: 'trend', month: group.month, data: group.data })}
                      >
                          <div className="flex justify-between items-center mb-2">
                              <span className="font-semibold text-sm text-slate-700">{group.month}</span>
                              <Maximize2 className="w-3 h-3 text-slate-400 group-hover:text-blue-500" />
                          </div>
                          <div className="h-32">
                              <ResponsiveContainer width="100%" height="100%">
                                  <LineChart data={group.chartData}>
                                      <Line type="monotone" dataKey="accuracyPct" stroke="#3B82F6" strokeWidth={2} dot={false} />
                                      <YAxis domain={[0, 100]} hide />
                                      <XAxis dataKey="shortDate" hide />
                                      <Tooltip labelStyle={{fontSize:'10px'}} itemStyle={{fontSize:'10px'}} />
                                  </LineChart>
                              </ResponsiveContainer>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      )}

