# 我们可以计算单点的 (R-F)^2 * |R-F|
result = (diff ** 2) * abs(diff)`,

  'Northeast': `# 变量说明: real(实测), fore_list(预测列表), cap(容量)
import numpy as np

# 1. 获取该时刻的预测均值 (fore_list 是该时刻的多家预测值列表)
mean_fore = np.mean(fore_list)

