        err = abs((mean_fore - real) / mean_fore)
        result = min(err, 1.0) # 误差最大限制为 1

# 结果 result 将被收集，最后取均值计算准确率`,

  'General': `diff = abs(real - fore)
result = diff ** 2  # 计算平方误差`
};

